// 05-styles/90-styles.js — порядок блоков стилей.
// Каждый блок обязан остаться отдельным элементом <style>: одним большим
// куском браузер принимает такой CSS лишь частично (проверено на живом интерфейсе).
const STYLES = [
  STYLE_FRAME,
  STYLE_SIDEBAR_DRAWER,
  STYLE_COMPOSER_WIDTH,
  STYLE_BRAND_COLORS,
  STYLE_TOUCH_BEHAVIOR,
  STYLE_COMPOSER_FONT,
  STYLE_HEADER_ACTIONS,
  STYLE_BACKDROP,
  STYLE_HEADER_STATUS,
  STYLE_STATS_DOCK,
  STYLE_MENU_BUTTON_BASE,
  STYLE_MENU_BUTTON,
  STYLE_PAGE_FIT,
  STYLE_SETTINGS_SCREEN,
  STYLE_SESSION_LOADING,
  STYLE_SCROLL_BUTTON,
]
// 05-styles/91-install-styles.js — добавить блоки стилей в документ.
/** Добавить блоки стилей, если их ещё нет. */
function installStyles() {
  for (let index = 0; index < STYLES.length; index++) {
    if (document.querySelector(`style[${MARKER}="${index}"]`) !== null) continue
    const tag = document.createElement('style')
    tag.setAttribute(MARKER, String(index))
    tag.textContent = STYLES[index]
    document.head.appendChild(tag)
  }
}
// 05-styles/92-remove-styles.js — убрать все блоки стилей из документа.
/** Убрать блоки стилей. */
function removeStyles() {
  for (const tag of document.querySelectorAll(`style[${MARKER}]`)) tag.remove()
}
// 06-viewport.js — высота кадра по видимой области и meta против зума.
function syncFrameHeight() {
  const root = document.documentElement
  const viewport = window.visualViewport
  if (viewport === undefined || viewport === null) {
    root.style.removeProperty(FRAME_HEIGHT_VAR)
    return
  }
  const visible = Math.round(viewport.height + viewport.offsetTop)
  const layout = Math.round(window.innerHeight)
  if (layout - visible < KEYBOARD_MIN_INSET) {
    root.style.removeProperty(FRAME_HEIGHT_VAR)
    return
  }
  root.style.setProperty(FRAME_HEIGHT_VAR, `${visible}px`)
}

/**
 * Следить за видимой областью.
 * @returns функция очистки.
 */
function installViewportTracking() {
  const viewport = window.visualViewport
  let scheduled = false
  // События идут пачками по нескольку за кадр: считаем не чаще одного раза.
  const onViewportChange = () => {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(() => {
      scheduled = false
      syncFrameHeight()
    })
  }

  window.addEventListener('resize', onViewportChange)
  window.addEventListener('orientationchange', onViewportChange)
  if (viewport !== undefined && viewport !== null) {
    viewport.addEventListener('resize', onViewportChange)
    viewport.addEventListener('scroll', onViewportChange)
  }
  syncFrameHeight()

  return () => {
    window.removeEventListener('resize', onViewportChange)
    window.removeEventListener('orientationchange', onViewportChange)
    if (viewport !== undefined && viewport !== null) {
      viewport.removeEventListener('resize', onViewportChange)
      viewport.removeEventListener('scroll', onViewportChange)
    }
    document.documentElement.style.removeProperty(FRAME_HEIGHT_VAR)
  }
}

/** Есть ли ключ в строке `content` у `<meta name="viewport">`. */
function hasViewportKey(content, key) {
  return new RegExp(`(^|[,;\\s])${key}\\s*=`, 'i').test(content)
}

/**
 * Дописать в `<meta name="viewport">` ключи против зума.
 *
 * Телефон увеличивает интерфейс в двух случаях: фокус попадает в поле с
 * шрифтом меньше 16px (лечится `maximum-scale=1`) и двойной тап по элементу
 * (лечится `touch-action: manipulation` в CSS). `maximum-scale=1` при этом
 * оставляет `initial-scale=1`, поэтому текст и вёрстка не уменьшаются.
 *
 * `interactive-widget=resizes-content` — штатный способ Chrome укоротить
 * layout viewport вместе с клавиатурой; Safari его игнорирует, и там работу
 * делает {@link syncFrameHeight}.
 *
 * @returns функция очистки.
 */
function installViewportMeta() {
  let meta = document.querySelector('meta[name="viewport"]')
  const created = meta === null
  if (created) {
    meta = document.createElement('meta')
    meta.setAttribute('name', 'viewport')
    meta.setAttribute('content', 'width=device-width, initial-scale=1')
    document.head.appendChild(meta)
  }
  const original = meta.getAttribute('content') ?? ''
  const keys = ['maximum-scale=1', 'interactive-widget=resizes-content']
  const prepared = original.trim().replace(/[,;]$/, '')
  const missing = keys.filter((key) => !hasViewportKey(prepared, key.split('=')[0]))
  if (missing.length > 0) {
    meta.setAttribute('content', [prepared, ...missing].filter((part) => part !== '').join(', '))
  }
  return () => {
    if (created) {
      meta.remove()
      return
    }
    meta.setAttribute('content', original)
  }
}
// 07-panel.js — геометрия панели, её переключение и состояние на корне документа.
function findToggle() {
  const panel = document.querySelector("[class$='_sidebarCol']")
  return panel === null ? null : panel.querySelector("[class$='_toggle']")
}

/**
 * Панель сейчас на экране?
 *
 * Одного атрибута `data-sidebar-collapsed` мало: он отражает намерение
 * harness, а не факт. Поэтому дополнительно смотрим на геометрию выдвинутой
 * панели — свёрнутая уезжает за левый край на свою ширину.
 */
function isPanelShown() {
  const panel = document.querySelector("[class$='_sidebarCol']")
  if (panel === null) return false
  const style = window.getComputedStyle(panel)
  if (style.visibility === 'hidden' || style.display === 'none') return false
  const rect = panel.getBoundingClientRect()
  // Пустой прямоугольник — панель спрятана предком: собственный `display` у неё
  // при этом обычный, а геометрия нулевая, и порог по `left` дал бы «показана».
  if (rect.width <= 0 || rect.height <= 0) return false
  return rect.left > -PANEL_VISIBLE_LEFT_PX
}

/**
 * Немедленно применить позу панели.
 *
 * Назначается {@link installPanelState}; до установки слоя делать нечего.
 *
 * Позу пересчитывают наблюдатель и страховочный интервал, то есть с задержкой до
 * полусекунды. Открытию и закрытию по тапу ждать нельзя: человек успевал нажать
 * кнопку ещё раз, пока панель не уехала, и второй тап попадал по ещё открытой
 * панели. Поэтому кнопка и закрытие применяют позу сами.
 */
let applyPanelGeometry = () => {}

/**
 * Переключить панель штатной кнопкой harness.
 *
 * Панель умеет прятаться так, что штатная кнопка перестаёт существовать.
 * Тогда снять затемнение обязан сам слой: закрыть панель иначе нечем, и
 * экран остался бы заблокированным.
 *
 * Кнопка слоя — единственный способ снова показать панель, поэтому именно она
 * снимает {@link panelClosedByLayer}. Флаг harness при этом может говорить
 * «развёрнута» (его вернула перерисовка после переключения чата): тогда
 * нажимать штатную кнопку нельзя — она свернула бы уже показанную панель, — и
 * достаточно просто снять наш флаг.
 */
function togglePanel() {
  const forced = panelClosedByLayer
  panelClosedByLayer = false
  // Новое открытие — новый жест: «карантин» предыдущего закрытия к нему не
  // относится, иначе первый же тап внутри снова открытой панели не закрыл бы её.
  lastCloseAt = 0
  // Панель возвращается этим же тапом, а не ближайшим пересчётом: иначе она
  // «не отвечает» на первое нажатие, и человек жмёт второй раз.
  applyPanelGeometry()
  const frame = document.querySelector("[class$='_frame']")
  const collapsedByHarness = frame !== null && frame.hasAttribute('data-sidebar-collapsed')
  // Флаг снят, панель по флагу harness развёрнута — она уже на экране.
  if (forced && !collapsedByHarness) return
  const control = findToggle()
  if (control !== null) {
    control.click()
    return
  }
  document.documentElement.removeAttribute(PANEL_ATTR)
}

/**
 * Когда панель закрывали в последний раз.
 *
 * Один тап приходит несколькими событиями — `touchstart`, `pointerdown` и
 * `click`, — и каждое просит закрыть панель. Закрытие сводится к нажатию
 * штатной кнопки, то есть к переключению: второе нажатие на тот же тап
 * возвращает панель обратно. Снаружи это выглядит как мигание панели, при
 * котором вдобавок ничего не нажимается — тап к тому же погашен.
 */
let lastCloseAt = 0

/**
 * Закрыта ли панель по решению слоя.
 *
 * Раньше здесь стоял «карантин» на 400 мс: панель держалась закрытой, пока
 * harness не перепишет свой флаг. На медленном телефоне этого окна не хватало:
 * перерисовка списка сессий возвращала `data-sidebar-collapsed=false` уже после
 * карантина, наш пересчёт видел «панель открыта» — и панель приезжала обратно
 * поверх только что открытого чата. Со стороны это выглядело как «тап по сессии
 * ничего не делает: остаётся тот же экран».
 *
 * Теперь это не таймер, а состояние: закрыли — значит закрыто, пока человек сам
 * не нажмёт кнопку слоя ({@link togglePanel}).
 */
let panelClosedByLayer = false

/**
 * Закрыть показанную панель.
 *
 * Панель уезжает только нашими инлайновыми стилями — штатную кнопку harness
 * здесь НЕ нажимаем, и это важно.
 *
 * Нажатие штатной кнопки переводит панель из развёрнутого состояния в рейл, а
 * вместе с ним React размонтирует развёрнутый список: строка сессии исчезает из
 * документа, и открытие, начатое этим же тапом, теряет ссылку на сессию. В
 * консоли это `Session reference "…" is released`, а на экране — вечное
 * «Loading history…»: телефон медленный, открытие ещё в полёте, список уже
 * размонтирован. На быстром клиенте гонка не видна, поэтому раньше казалось, что
 * «всё работает».
 *
 * Инлайновый `transform` перебивает и каскад, и флаг harness, а список при этом
 * остаётся смонтированным — открытие доходит до конца. Пересчёт геометрии
 * (см. {@link installPanelState}) применяет позу закрытой панели.
 *
 * Повторный вызов внутри одного жеста игнорируется — см. {@link lastCloseAt}.
 */
function closePanel() {
  const now = Date.now()
  if (now - lastCloseAt < PANEL_CLOSE_GUARD_MS) return
  lastCloseAt = now
  // Панель уезжает сразу и больше не возвращается, даже если harness ещё не
  // переписал свой флаг сворачивания.
  panelClosedByLayer = true
  // Уезжает именно этим вызовом: ближайший пересчёт мог быть через полсекунды,
  // и всё это время панель оставалась поверх выбранного чата.
  applyPanelGeometry()
  // Затемнение и его перехват тапов снимаем сразу: иначе слой полсекунды (до
  // ближайшего пересчёта) продолжал бы съедать нажатия по загруженному чату.
  document.documentElement.removeAttribute(PANEL_ATTR)
}

/**
 * Тап меняет то, что видно за панелью: чат, панель или диалог настроек.
 *
 * Такой тап закрывает панель. Одной строки сессии мало: «New Session» создаёт
 * чат, «Plugins» открывает панель, «Settings» — диалог, и во всех трёх случаях
 * выдвинутая панель оставалась поверх только что открытого экрана.
 */
function isPanelNavigation(target) {
  return target instanceof Element &&
    target.closest(`${SESSION_ROW_SELECTOR}, [class$='_newSession'], [class$='_panelRow'], [class$='_triggerRow'], a[href]`) !== null
}

/** Тап пришёл по строке сессии? */
function isSessionRow(target) {
  return target instanceof Element && target.closest(SESSION_ROW_SELECTOR) !== null
}

/** Тап пришёл по самой панели? Тогда закрывать нечего. */
function isInsidePanel(target) {
  const panel = document.querySelector("[class$='_sidebarCol']")
  return panel !== null && target instanceof Node && panel.contains(target)
}

/**
 * Держать на корне документа состояние «панель на экране».
 *
 * По этому состоянию включается затемнение, поэтому оно обязано совпадать с
 * реальностью, а не с намерением harness: смотрим на разметку панели и на
 * смену раскладки.
 *
 * @returns функция очистки.
 */
function installPanelState() {
  // См. {@link installDrawer}: на широком экране состояние панели не считаем —
  // иначе слой вешает на корень документа `data-dsh-mobile-panel`, по которому
  // включается затемнение, и начинает спорить с раскладкой harness.
  if (!isNarrow()) return () => {}

  const root = document.documentElement
  let scheduled = false
  let scheduledAt = 0
  let lastRun = 0
  let settleTimer = null

  /**
   * Задать панели геометрию инлайновыми стилями.
   *
   * Правила слоя — обычный CSS, и если на устройстве какое-то из них не
   * применилось, панель возвращалась к штатной ширине и «схлопывалась» до рейла
   * (56px) при нажатии на кнопку сворачивания — со стороны это выглядело как
   * закрытие в два шага. Инлайновые стили перебивают таблицы стилей, поэтому
   * открытие и закрытие теперь не зависят от каскада.
   */
  const applyGeometry = () => {
    const side = document.querySelector("[class$='_sidebarCol']")
    if (side === null) return
    const frame = document.querySelector("[class$='_frame']")
    // Решение слоя важнее флага harness: см. {@link panelClosedByLayer}.
    const collapsed = panelClosedByLayer || (frame !== null && frame.hasAttribute('data-sidebar-collapsed'))
    // Та же ширина, что и в CSS: правый край проходит между «+» и «⋮», поэтому
    // в полосе справа видно только «⋮».
    const width = Math.min(window.innerWidth - 56, 420)
    const style = side.style
    style.position = 'fixed'
    style.top = '0'
    style.bottom = '0'
    style.left = '0'
    style.width = `${Math.max(width, 280)}px`
    style.zIndex = '60'
    style.transition = 'transform 0.26s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.26s'
    style.transform = collapsed ? 'translateX(-105%)' : 'none'
    style.visibility = collapsed ? 'hidden' : 'visible'
    // Колонки кадра фиксируем: панель на телефоне и так вынесена из раскладки
    // (position: fixed), но harness при открытии/сворачивании переписывает
    // `grid-template-columns` (280px ↔ 56px), и контент на кадр успевал
    // пересчитаться — со стороны это выглядело как «всё растянулось».
    if (frame !== null && frame.style.gridTemplateColumns !== MOBILE_GRID_COLUMNS) {
      frame.style.gridTemplateColumns = MOBILE_GRID_COLUMNS
    }
    // Внутренняя колонка панели и отступы её строк — тоже инлайново. Список
    // сессий harness перерисовывает при каждом переключении чата, и если в этот
    // момент класс колонки оказывается другим, правила слоя на кадр перестают
    // совпадать: строки успевают разъехаться на всю ширину и вернуться — со
    // стороны это выглядело как «границы меню разделяются и снова сдвигаются».
    //
    // Колонку ищем по строке с логотипом, а не по имени класса: после закрытия и
    // повторного открытия harness пересобирает панель, и класс `_quietBars`
    // пропадает (остаётся `_root`). Тогда инлайновые отступы попадали не тому
    // элементу — строки уезжали вправо, а содержимое вылезало за панель.
    const logoRow = side.querySelector("[class*='_logoRow']")
    const inner = logoRow?.parentElement ?? side.querySelector("[class*='_quietBars']") ?? side.firstElementChild
    if (inner !== null) {
      inner.style.width = '100%'
      inner.style.paddingLeft = '2px'
      inner.style.paddingRight = '2px'
      for (const child of inner.children) {
        const logo = String(child.className ?? '').includes('_logoRow')
        const inset = logo ? '0px' : '20px'
        if (child.style.marginLeft !== inset) child.style.marginLeft = inset
        if (child.style.marginRight !== inset) child.style.marginRight = inset
      }
    }
  }

  const apply = () => {
    scheduled = false
    lastRun = Date.now()
    applyGeometry()
    const open = isNarrow() && isPanelShown()
    const next = open ? 'open' : null
    if (root.getAttribute(PANEL_ATTR) !== next) {
      if (next === null) root.removeAttribute(PANEL_ATTR)
      else root.setAttribute(PANEL_ATTR, next)
    }
  }
  // Тап по кнопке слоя и закрытие панели по тапу применяют позу сразу, не
  // дожидаясь наблюдателя: см. {@link applyPanelGeometry}.
  applyPanelGeometry = applyGeometry
  // Панель появляется в разметке не мгновенно: считаем состояние по кадру,
  // чтобы не поймать ещё пустой документ.
  const schedule = () => {
    if (scheduled) return
    scheduled = true
    scheduledAt = Date.now()
    const wait = Math.max(0, PANEL_STATE_MIN_INTERVAL_MS - (scheduledAt - lastRun))
    if (wait === 0) requestAnimationFrame(apply)
    else window.setTimeout(() => requestAnimationFrame(apply), wait)
    // Панель выезжает 260мс, и сразу после смены класса геометрия ещё старая:
    // разовый пересчёт увидел бы «закрыто» и на этом остановился — затемнение
    // не включалось до следующей случайной перерисовки. Поэтому пересчитываем
    // ещё раз, когда анимация заведомо закончилась.
    clearTimeout(settleTimer)
    settleTimer = window.setTimeout(() => requestAnimationFrame(apply), PANEL_SETTLE_MS)
  }

  // Наблюдаем весь документ: панель и её атрибуты появляются и меняются в
  // любой момент, а привязка к конкретным узлам ломается при их пересоздании.
  //
  // Геометрию переставляем сразу, до отрисовки кадра, но только когда мутация
  // касается кадра или панели: при потоковом ответе мутации идут сотнями в
  // секунду, и пересчёт на каждую подвешивал телефон.
  const relevant = (records) => {
    const side = document.querySelector("[class$='_sidebarCol']")
    const frame = document.querySelector("[class$='_frame']")
    if (side === null) return false
    for (const record of records) {
      const target = record.target
      if (!(target instanceof Node)) continue
      if (side.contains(target) || (frame !== null && frame.contains(target))) return true
      if (target instanceof Element && target.querySelector?.("[class$='_sidebarCol']") != null) return true
    }
    return false
  }
  const observer = new MutationObserver((records) => {
    if (relevant(records)) applyGeometry()
    schedule()
  })
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['style', 'class', 'data-sidebar-collapsed'],
    childList: true,
    subtree: true,
  })
  window.addEventListener('resize', schedule)
  window.addEventListener('orientationchange', schedule)
  schedule()
  // Страховка от залипшего состояния: если затемнение осталось включённым, а
  // панель уже уехала (или наоборот), один пересчёт в полсекунды это исправит.
  // Иначе полноэкранное затемнение молча съедало бы все тапы — «интерфейс
  // завис», и переключиться по чатам было нельзя.
  const heartbeat = window.setInterval(apply, 500)

  return () => {
    observer.disconnect()
    window.removeEventListener('resize', schedule)
    window.removeEventListener('orientationchange', schedule)
    clearTimeout(settleTimer)
    clearInterval(heartbeat)
    applyPanelGeometry = () => {}
    root.removeAttribute(PANEL_ATTR)
  }
}
// 08-drawer.js — кит-кнопка в шапке, затемнение и обработчики нажатий.
function installDrawer() {
  // Слой выдвижной панели существует только на телефоне. На широком экране
  // панель harness стоит в раскладке и видна всегда — и тогда
  // {@link isPanelShown} отвечает «показана» на каждом нажатии: обработчики
  // ниже принимали любой клик за «нажатие вне панели» и сворачивали её. Панель
  // уезжала, harness возвращал её назад, следующий клик повторял цикл — со
  // стороны это выглядит как «страница дёргается и не нажимается» (проверено на
  // живой сборке: `data-sidebar-collapsed` мигал каждые ~300мс).
  if (!isNarrow()) return () => {}

  let button = null

  // Кит живёт в шапке, а шапку React рисует не сразу: в момент запуска слоя её
  // может ещё не быть. Поэтому кнопку ставим лениво — сразу, если шапка уже
  // есть, иначе по факту её появления (наблюдатель в конце функции).
  const ensureButton = () => {
    if (button !== null && button.isConnected) return button
    button = document.querySelector(`.${BUTTON_CLASS}`)
    if (button === null) {
      const header = document.querySelector(HEADER_SELECTOR)
      if (header === null) {
        button = null
        return null
      }
      button = document.createElement('button')
      button.className = BUTTON_CLASS
      button.type = 'button'
      button.title = 'Меню'
      button.setAttribute('aria-label', 'Открыть панель')
      button.addEventListener('click', togglePanel)
      header.appendChild(button)
    }
    // Логотип ставим и в уже существующей кнопке: при перезагрузке плагина
    // элемент остаётся в документе, а разметка могла остаться прежней.
    button.innerHTML = WHALE_BUTTON_SVG
    return button
  }

  let backdrop = document.querySelector(`.${BACKDROP_CLASS}`)
  if (backdrop === null) {
    backdrop = document.createElement('div')
    backdrop.className = BACKDROP_CLASS
    backdrop.setAttribute('aria-hidden', 'true')
    document.body.appendChild(backdrop)
  }

  /**
   * Нажатие вне панели закрывает её.
   *
   * Слушаем `pointerdown` и `touchstart` прямо на документе и в фазе
   * перехвата: `click` на телефоне может не прийти вовсе, а тогда затемнение
   * висело бы до перезагрузки. Реагируем раньше содержимого, чтобы тап не
   * успел сработать как нажатие по тому, что из-под панели видно.
   *
   * Внутри панели нажатие НЕ закрывает её — даже по строке сессии. Закрытие
   * сводится к нажатию штатной кнопки, панель уезжает из-под пальца, и `click`
   * достаётся уже другому элементу: переключение чата не срабатывало (проверено
   * настоящим тачем). Навигация закрывает панель по `click` — см.
   * {@link onDocumentClick}, где тап уже доставлен строке.
   *
   * Раньше здесь же стоял запрет на повторный тап по списку, пока идёт
   * загрузка: тап гасился, а каждое гашение заново поднимало полосу загрузки
   * ({@link installSessionLoading}) — и выйти из этого состояния было нечем.
   * Загрузка истории на телефоне идёт секундами, поэтому через пару тапов экран
   * замирал насовсем: список виден, панель открыта, выбранный чат не
   * открывается. Теперь тап по строке доходит до React всегда, а потерянный
   * тап повторяет {@link armRescue}.
   */
  const onOutsidePress = (event) => {
    const target = event.target
    const inside = isInsidePanel(target)
    // Новый жест по другому месту отменяет прежнюю страховку тапа: см.
    // {@link armRescue}.
    if (!inside) cancelRescue()
    // Затемнение могло остаться включённым, когда панель уже уехала (например,
    // после возврата из настроек или перерисовки). Тогда этот слой молча съедал
    // бы все тапы — «ничего не нажимается». Поэтому: снимаем состояние и
    // пропускаем событие дальше, ничего не гася.
    if (!isPanelShown()) {
      if (document.documentElement.getAttribute(PANEL_ATTR) !== null) {
        document.documentElement.removeAttribute(PANEL_ATTR)
      }
      return
    }
    if (inside) return
    if (target instanceof Element && target.closest(`.${BUTTON_CLASS}`) !== null) return
    event.preventDefault()
    event.stopPropagation()
    closePanel()
  }

  /** Поле ввода под панелью: фокус в него закрывает панель. */
  const onFocusIn = (event) => {
    if (!isPanelShown()) return
    const target = event.target
    if (isInsidePanel(target)) return
    if (target instanceof Element && target.closest('input, textarea, [contenteditable="true"]') === null) return
    closePanel()
  }

  /**
   * Заголовок открытого чата. `null` — заголовка нет (новый чат): сверять нечего.
   *
   * Смена заголовка — единственный дешёвый признак того, что переключение
   * началось: harness ставит его сразу, ещё до того как подъедет история.
   */
  const currentChatTitle = () => {
    const crumbs = document.querySelector("[class$='_crumbs']")
    return crumbs === null ? null : (crumbs.textContent ?? '').trim()
  }

  /** Отложенное повторение тапа по строке сессии: см. {@link armRescue}. */
  let rescueTimer = 0
  let rescueTap = null

  const cancelRescue = () => {
    if (rescueTimer !== 0) {
      window.clearTimeout(rescueTimer)
      rescueTimer = 0
    }
    rescueTap = null
  }

  /**
   * Доовести тап по строке сессии до переключения.
   *
   * На телефоне тап по строке иногда не доходит до React: браузер отдаёт его
   * наведению (у строки есть карточка и бегущий заголовок), считает началом
   * прокрутки или не синтезирует `click` внутри списка. Снаружи это выглядит
   * так, будто чат открывается только со второго раза, — и человек
   * действительно жмёт второй раз, после чего всё работает.
   *
   * Поэтому повторяем ровно это: ждём {@link SESSION_TAP_RESCUE_MS} и, если
   * заголовок чата не сменился, нажимаем тот же узел программно. Настоящий
   * `click` отменяет страховку ({@link onDocumentClick}), так что при живом тапе
   * второго нажатия не будет.
   *
   * Панель до срабатывания не закрываем: строка должна остаться в разметке.
   */
  const armRescue = (target) => {
    const row = target instanceof Element ? target.closest(SESSION_ROW_SELECTOR) : null
    if (row === null) return
    const before = currentChatTitle()
    // Тап по уже открытому чату: переключаться некуда, повторять нечего. В
    // строке заголовок стоит вместе с пометкой статуса и временем, поэтому
    // сверяем по началу.
    if (before !== null && before !== '' &&
      (row.textContent ?? '').includes(before.slice(0, SESSION_TITLE_MATCH_MAX))) return
    cancelRescue()
    rescueTap = { element: target, row }
    rescueTimer = window.setTimeout(() => {
      rescueTimer = 0
      const tap = rescueTap
      rescueTap = null
      if (tap === null) return
      // Строку могли перерисовать: тогда жмём тот же узел, а если и он ушёл из
      // документа — саму строку.
      const element = tap.element.isConnected ? tap.element : tap.row
      if (!element.isConnected) return
      if (currentChatTitle() !== before) {
        // Переключение уже началось, а `click` до слоя не дошёл — закрываем
        // панель сами, иначе она осталась бы поверх открытого чата.
        closePanel()
        return
      }
      element.click()
    }, SESSION_TAP_RESCUE_MS)
  }

  /**
   * `click` дообрабатывает то, что не должен трогать `pointerdown`: закрытие
   * панели по тапу на строку сессии или на ссылку.
   *
   * Закрытие отложено на макрозадачу: сначала событие должно дойти до React и
   * переключить чат, и только потом панель уезжает. Раньше кнопка сворачивания
   * нажималась прямо в обработчике — панель перерисовывалась раньше, чем
   * доходил `click`, и переключение чата терялось: меню оставалось открытым, а
   * выбранный чат не открывался.
   */
  const deferClose = () => {
    cancelPendingClose()
    window.setTimeout(() => { closePanel() }, 0)
  }

  /**
   * Отложенное закрытие на случай, когда `click` по строке не приходит вовсе.
   *
   * Ждём дольше, чем браузер тратит на синтетический `click`: если пришёл
   * `click`, он отменит это закрытие и закроет панель сам — уже после того, как
   * тап дойдёт до React. Иначе панель уезжала раньше строки, строка исчезала из
   * разметки, и чат не открывался: полоса загрузки гасла на пустом экране.
   */
  let pendingClose = 0
  const cancelPendingClose = () => {
    if (pendingClose !== 0) {
      window.clearTimeout(pendingClose)
      pendingClose = 0
    }
  }

  const onDocumentClick = (event) => {
    const target = event.target
    if (isInsidePanel(target)) {
      // Тап внутри панели закрывает её только если он что-то открывает. Проверку
      // «панель показана» здесь не делаем: на медленном телефоне геометрия в
      // момент доставки `click` уже могла отстать, и тап по строке не закрывал
      // панель вовсе — чат менялся под ней, а экран оставался тем же.
      if (!isPanelNavigation(target)) return
      // Тап дошёл сам — повторное нажатие не нужно: см. {@link armRescue}.
      cancelRescue()
      deferClose()
      return
    }
    if (!isPanelShown()) return
    cancelPendingClose()
    if (target instanceof Element && target.closest(`.${BUTTON_CLASS}`) !== null) return
    closePanel()
  }

  /**
   * Тап по строке сессии: страховка на случай, когда `click` до нас не дошёл.
   *
   * На части браузеров (и в установленном приложении) тап по элементу внутри
   * прокручиваемого списка не даёт `click` — тогда меню оставалось открытым.
   * Для строки сессии закрытие по таймеру не годится: строка исчезла бы из
   * разметки раньше, чем до неё дошёл {@link armRescue}.
   */
  const onPanelPress = (event) => {
    const target = event.target
    if (!isInsidePanel(target)) return
    if (!isPanelNavigation(target)) return
    cancelPendingClose()
    if (isSessionRow(target)) {
      armRescue(target)
      return
    }
    pendingClose = window.setTimeout(() => {
      pendingClose = 0
      closePanel()
    }, PANEL_CLICK_FALLBACK_MS)
  }

  document.addEventListener('pointerdown', onOutsidePress, true)
  document.addEventListener('touchstart', onOutsidePress, { capture: true, passive: false })
  document.addEventListener('pointerup', onPanelPress, true)
  document.addEventListener('touchend', onPanelPress, true)
  document.addEventListener('focusin', onFocusIn, true)
  document.addEventListener('click', onDocumentClick, true)

  ensureButton()
  // Шапка может перерисоваться (React меняет разметку) и унести кнопку с собой —
  // тогда возвращаем её на место.
  const observer = new MutationObserver(() => {
    if (button === null || !button.isConnected) ensureButton()
  })
  observer.observe(document.body, { childList: true, subtree: true })

  return () => {
    observer.disconnect()
    cancelRescue()
    cancelPendingClose()
    document.removeEventListener('pointerdown', onOutsidePress, true)
    document.removeEventListener('touchstart', onOutsidePress, true)
    document.removeEventListener('pointerup', onPanelPress, true)
    document.removeEventListener('touchend', onPanelPress, true)
    document.removeEventListener('focusin', onFocusIn, true)
    document.removeEventListener('click', onDocumentClick, true)
    if (button !== null && button.isConnected) button.remove()
    backdrop.remove()
  }
}
// 09-manifest.js — манифест приложения и иконки в документе.
function installAppIcons() {
  const head = document.head
  const created = []
  const add = (tag) => {
    head.appendChild(tag)
    created.push(tag)
  }
  const addLink = (rel, href, extra = {}) => {
    const tag = document.createElement('link')
    tag.rel = rel
    tag.href = href
    for (const [name, value] of Object.entries(extra)) tag.setAttribute(name, value)
    add(tag)
  }

  const manifest = JSON.stringify({
    name: APP_NAME,
    short_name: APP_SHORT_NAME,
    start_url: '/',
    scope: '/',
    display: 'standalone',
    background_color: '#ffffff',
    theme_color: '#ffffff',
    icons: APP_ICONS.map(([sizes, dataUrl, purpose]) => ({
      src: dataUrl,
      sizes: `${sizes}x${sizes}`,
      type: 'image/png',
      purpose,
    })),
  })
  let manifestUrl = null
  try {
    manifestUrl = URL.createObjectURL(new Blob([manifest], { type: 'application/manifest+json' }))
  } catch (error) {
    console.warn(`dsh-plugin-mobile-ui: could not build the app manifest: ${String(error)}`)
  }

  // Штатная ссылка на манифест: если своя не собралась, оставляем её.
  const existingManifest = document.querySelector('link[rel="manifest"]')
  if (existingManifest === null && manifestUrl !== null) {
    addLink('manifest', manifestUrl)
  } else if (existingManifest !== null && manifestUrl !== null) {
    existingManifest.href = manifestUrl
  }

  // Иконки ярлыка тоже уходят data URL: файл по абсолютному адресу отдаётся
  // как octet-stream (см. комментарий к APP_ICON_*).
  addLink('apple-touch-icon', APP_ICON_180, { sizes: '180x180' })
  addLink('icon', APP_ICON_32, { type: 'image/png', sizes: '32x32' })
  addLink('icon', APP_ICON_192, { type: 'image/png', sizes: '192x192' })

  const meta = (name, content) => {
    const tag = document.createElement('meta')
    tag.name = name
    tag.content = content
    add(tag)
  }
  meta('apple-mobile-web-app-capable', 'yes')
  meta('apple-mobile-web-app-title', APP_SHORT_NAME)
  meta('apple-mobile-web-app-status-bar-style', 'default')
  meta('theme-color', '#ffffff')

  return () => {
    for (const tag of created) tag.remove()
    if (existingManifest !== null && manifestUrl !== null) existingManifest.href = './manifest.webmanifest'
    if (manifestUrl !== null) URL.revokeObjectURL(manifestUrl)
  }
}
// 10-header-menu.js — пункты Relay и «открыть в проводнике» в меню «⋮».
const MORE_ACTIONS_SELECTOR = '[aria-label="More actions"]'

/** Шапка сессии. `*=` ловит и пустую шапку (`_headerBlank`), где суффикс не последний. */
const HEADER_SELECTOR = 'header[class*="_header"]'

/** Штатный счётчик фоновых задач — источник статуса. */
const HEADER_ACTIONS_SELECTOR = "[class$='_headerActions']"

/** Штатная кнопка «открыть в проводнике» — иконка с папкой слева от «⋮». */
const EXPLORER_SELECTOR = '[aria-label="Open in File Explorer"]'

/** Ссылка Relay: её рисует отдельный плагин, id стабилен. */
const RELAY_LINK_ID = 'dsh-relay-link'

/** Метка на пункте меню, который добавил этот слой. */
const MENU_ITEM_ATTR = 'data-dsh-plugin-mobile-ui-menu-item'

/** Виден ли элемент: свёрнутая панель и закрытые меню дают нулевой прямоугольник. */
function isVisible(element) {
  const rect = element.getBoundingClientRect()
  return rect.width > 0 && rect.height > 0 && getComputedStyle(element).visibility !== 'hidden'
}

/**
 * Меню, в которое можно подмешать пункты.
 *
 * Берём последнее видимое `role="menu"`: попапы уезжают в конец `body`, поэтому
 * последнее — то, что только что открылось.
 */
function findOpenMenu() {
  const menus = [...document.querySelectorAll('[role="menu"]')].filter(isVisible)
  return menus.length === 0 ? null : menus[menus.length - 1]
}

/** Закрыть открытые меню: «Escape» — штатный для них жест. */
function closeOpenMenus() {
  for (const menu of document.querySelectorAll('[role="menu"]')) {
    menu.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }))
  }
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }))
}

/** Выполнить действие переехавшего пункта: нажимаем ту самую штатную кнопку. */
function runHeaderAction(kind) {
  const target = kind === 'relay'
    ? document.getElementById(RELAY_LINK_ID)
    : document.querySelector(EXPLORER_SELECTOR)
  closeOpenMenus()
  if (target === null) return
  // Штатная кнопка прячется через `display: none`, но обработчик у неё живой:
  // программный `click` доходит до React так же, как настоящий.
  target.click()
}

/**
 * Собрать пункт меню из штатного шаблона.
 *
 * Клонируем готовую обёртку вместе с кнопкой: так пункт приезжает с родными
 * классами, отступами и иконкой. Меняем только подпись и картинку.
 */
function buildMenuItem(template, source) {
  const wrap = template.parentElement?.cloneNode(true)
  if (wrap === undefined || wrap === null) return null
  const button = wrap.querySelector('[role="menuitem"]')
  if (button === null) return null

  button.setAttribute(MENU_ITEM_ATTR, source.kind)
  const icon = button.querySelector('[class*="_itemIcon"]')
  if (icon !== null) {
    icon.replaceChildren()
    if (source.icon !== null) icon.appendChild(source.icon.cloneNode(true))
  }
  const labelNode = [...button.querySelectorAll('span')]
    .reverse()
    .find((span) => span.children.length === 0 && span.textContent.trim() !== '')
  if (labelNode === undefined) button.append(source.label)
  else labelNode.textContent = source.label

  button.addEventListener('click', (event) => {
    // Без остановки событие дойдёт до React, и он примет его за клик по меню.
    event.preventDefault()
    event.stopPropagation()
    runHeaderAction(source.kind)
  })
  return wrap
}

/**
 * Подмешать Relay и «папку» в открытое меню «⋮».
 * @returns сколько пунктов добавлено (0 — если меню не то или уже размечено).
 */
function addHeaderMenuItems(menu) {
  // Слой существует только на узких экранах. На широком десктопе Relay и
  // «папка» стоят в шапке и никому не мешают — второй раз они там не нужны.
  if (!window.matchMedia(`(max-width: ${NARROW_MAX_PX}px)`).matches) return 0
  if (menu.querySelector(`[${MENU_ITEM_ATTR}]`) !== null) return 0
  const template = menu.querySelector('[role="menuitem"]')
  const container = template?.parentElement?.parentElement
  if (template === null || template === undefined || container === undefined || container === null) return 0

  const sources = []
  const relayLink = document.getElementById(RELAY_LINK_ID)
  if (relayLink !== null) {
    sources.push({ kind: 'relay', label: 'Relay', icon: relayLink.querySelector('svg') })
  }
  const explorer = document.querySelector(EXPLORER_SELECTOR)
  if (explorer !== null) {
    sources.push({ kind: 'explorer', label: 'Open in File Explorer', icon: explorer.querySelector('img') })
  }

  let added = 0
  for (const source of sources) {
    const item = buildMenuItem(template, source)
    if (item === null) continue
    container.appendChild(item)
    added += 1
  }
  return added
}

/**
 * Следить за штатным меню «⋮» и добавлять в него переехавшие пункты.
 *
 * Меню — портал React, который создаётся в момент открытия и исчезает при
 * закрытии, поэтому его нельзя разметить один раз: подмешиваем по факту
 * появления. Подмешиваем только после нажатия на сами «три точки» — иначе можно
 * было бы влезть в чужое меню (например, в выбор модели).
 *
 * @returns функция очистки.
 */
function installHeaderActions() {
  let armed = false
  let disarmTimer = null
  let scheduled = false

  const sync = () => {
    scheduled = false
    if (!armed) return
    const menu = findOpenMenu()
    if (menu === null) return
    if (addHeaderMenuItems(menu) > 0) armed = false
  }
  const schedule = () => {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(sync)
  }

  const observer = new MutationObserver(schedule)
  observer.observe(document.body, { childList: true, subtree: true })

  const arm = (event) => {
    if (!(event.target instanceof Element)) return
    if (event.target.closest(MORE_ACTIONS_SELECTOR) === null) return
    armed = true
    clearTimeout(disarmTimer)
    disarmTimer = setTimeout(() => { armed = false }, 2000)
    // Меню может уже существовать (клик без pointerdown, повторное открытие) —
    // тогда наблюдатель не сработает и подмешать нужно прямо сейчас.
    schedule()
  }
  // pointerdown ловит палец, click — программные нажатия и клавиатуру.
  document.addEventListener('pointerdown', arm, true)
  document.addEventListener('click', arm, true)

  return () => {
    observer.disconnect()
    document.removeEventListener('pointerdown', arm, true)
    document.removeEventListener('click', arm, true)
    clearTimeout(disarmTimer)
    for (const item of document.querySelectorAll(`[${MENU_ITEM_ATTR}]`)) {
      item.closest('[role="menuitem"]')?.parentElement?.remove()
    }
  }
}
// 11-header-status.js — плашка с живым этапом работы в шапке.
/** Свести служебный текст к одной строке и убрать точки-анимацию в конце. */
function normalizeStatusText(raw) {
  return String(raw ?? '')
    .replace(/\s+/gu, ' ')
    .replace(/[\s·…]+$/gu, '')
    .trim()
}

function installHeaderStatus() {
  let slot = null
  let textNode = null
  let labelNode = null

  const narrow = () => window.matchMedia(`(max-width: ${NARROW_MAX_PX}px)`).matches

  const ensure = () => {
    if (slot !== null && slot.isConnected) return slot
    const header = document.querySelector(HEADER_SELECTOR)
    if (header === null) return null
    slot = document.createElement('div')
    slot.className = STATUS_CLASS
    slot.setAttribute('aria-hidden', 'true')
    textNode = document.createElement('span')
    textNode.className = `${STATUS_CLASS}-run`
    // Текст живёт в отдельном узле: у него свой `text-overflow`, поэтому
    // длинный этап обрезается многоточием, а точка-индикатор остаётся целой.
    labelNode = document.createElement('span')
    labelNode.className = `${STATUS_CLASS}-label`
    textNode.append(labelNode)
    slot.append(textNode)
    header.appendChild(slot)
    return slot
  }

  /**
   * Текущий инструмент: «Edit · 11-header-status.js».
   *
   * Активный вызов harness помечает `data-state="running"`; внутри у него есть
   * готовые название (`_title`) и подпись (`_summary`) — путь файла, команда,
   * запрос. Ничего не досчитываем сами.
   */
  const readRunningTool = () => {
    const tools = [...document.querySelectorAll(RUNNING_TOOL_SELECTOR)].filter(isVisible)
    if (tools.length === 0) return ''
    const tool = tools[tools.length - 1]
    const title = normalizeStatusText(tool.querySelector(TOOL_TITLE_SELECTOR)?.textContent)
    // У «Write» и «Edit» подписи `_summary` нет: путь файла лежит в ссылке.
    const detail = tool.querySelector(TOOL_SUMMARY_SELECTOR) ?? tool.querySelector(TOOL_FILE_SELECTOR)
    const summary = normalizeStatusText(detail?.textContent)
    if (title === '') return summary
    return summary === '' ? title : `${title} · ${summary}`
  }

  /**
   * Текст живой строки хода: «Deep diving for 6m 38s».
   *
   * Harness рисует её в конце переписки (`data-chat-running`), и существует она
   * только пока сессия работает. Служебные точки в конце — анимация, в плашке
   * они не нужны.
   */
  const readRunningStage = () => {
    const running = [...document.querySelectorAll(RUNNING_SELECTOR)].filter(isVisible)
    if (running.length === 0) return ''
    const node = running[running.length - 1]
    const label = node.querySelector(RUNNING_LABEL_SELECTOR) ?? node
    return normalizeStatusText(label.textContent)
  }

  /** Счётчики из шапки — то, что на десктопе стоит справа от режима работы. */
  const readHeaderCounters = () => {
    const header = document.querySelector(HEADER_SELECTOR)
    if (header === null) return ''
    return [...header.querySelectorAll(HEADER_COUNTER_SELECTOR)]
      .map((el) => normalizeStatusText(el.textContent))
      .filter((part) => part !== '')
      .join(' · ')
  }

  const render = () => {
    // Слот существует только на узком экране: на широком он остался бы без
    // стилей, потому что живёт внутри медиазапроса.
    if (!narrow()) {
      if (slot !== null) slot.remove()
      slot = null
      return
    }
    if (ensure() === null) return
    // Сначала — инструмент, который работает прямо сейчас; между вызовами
    // показываем живой этап хода, затем счётчики шапки. Заглушку («Running») не
    // пишем: слово, которое ничего не сообщает, вместо этапа только мешает.
    const tool = readRunningTool()
    const stage = readRunningStage()
    const next = tool !== '' ? tool : stage !== '' ? stage : readHeaderCounters()
    // Пусто — плашки нет совсем: в шапке остаются только кнопки.
    slot.style.display = next === '' ? 'none' : ''
    // Пишем только когда текст реально меняется: ниже стоит MutationObserver,
    // и если записывать то же значение, он снова вызовет render — вечный цикл.
    if (labelNode.textContent !== next) labelNode.textContent = next
  }

  render()
  // Разметка в живом чате меняется непрерывно — при потоковом ответе каждая
  // порция текста даёт мутацию. Пересчитывать плашку на каждую из них дорого:
  // три поиска по всему документу на токен подвешивали телефон. Поэтому
  // пересчёт не чаще раза в 120 мс.
  let scheduled = false
  let lastRun = 0
  const schedule = () => {
    if (scheduled) return
    scheduled = true
    const wait = Math.max(0, STATUS_RENDER_MIN_INTERVAL_MS - (Date.now() - lastRun))
    window.setTimeout(() => {
      scheduled = false
      lastRun = Date.now()
      render()
    }, wait)
  }
  const observer = new MutationObserver(schedule)
  observer.observe(document.body, { childList: true, subtree: true, characterData: true })
  window.addEventListener('resize', schedule)
  window.addEventListener('orientationchange', schedule)

  return () => {
    observer.disconnect()
    window.removeEventListener('resize', schedule)
    window.removeEventListener('orientationchange', schedule)
    if (slot !== null) slot.remove()
    slot = null
  }
}
// 12-stats-dock.js — полоса статистики: подъём наверх, замер высоты и своя полоса.
function installStatsDock() {
  const root = document.documentElement
  let empty = null
  let template = ''
  let builtFrom = null
  let builtText = null

  /** Живая полоса harness: есть в разметке или нет. */
  const liveStrip = () => document.querySelector(STATS_ROOT_SELECTOR)

  /**
   * Полоса реально видна в верхней строке экрана.
   *
   * Присутствия в разметке мало: harness может отрисовать полосу и спрятать её
   * (док `display: none` в момент загрузки сессии), а CSS-подъём может не
   * сработать — тогда полоса остаётся внизу за полем ввода. Отдельная беда —
   * полоса на своём месте в разметке, но **накрыта шапкой**: если отступ кадра
   * сверху не применился, шапка стоит в тех же 0..26px и закрывает её. Прямоугольник
   * при этом правильный, и проверка по координатам говорит «видна», хотя на
   * экране её нет. Поэтому в конце — проверка попаданием: в центре полосы должен
   * оказаться сам элемент полосы, а не шапка.
   */
  const stripVisible = () => {
    const live = liveStrip()
    if (live === null) return false
    const rect = live.getBoundingClientRect()
    if (rect.width < 8 || rect.height < 8) return false
    // Отрицательный top — полоса уехала выше экрана; это тоже «не видна».
    if (rect.top < -2 || rect.top > 8) return false
    const style = getComputedStyle(live)
    if (style.display === 'none' || style.visibility === 'hidden') return false
    const x = Math.round(rect.left + Math.min(rect.width / 2, 40))
    const y = Math.round(rect.top + rect.height / 2)
    // Свою полосу из проверки исключаем: она лежит поверх и с z-index 200
    // перехватила бы попадание — тогда получился бы замкнутый круг «своя
    // полоса видна, значит живая не видна, значит показываем свою».
    const stack = document.elementsFromPoint(x, y)
    const first = stack.find((el) => !(empty !== null && empty.contains(el)))
    if (first === undefined) return false
    return first === live || live.contains(first) || first.contains(live)
  }

  /** Текст живой полосы: по нему видно, что значения обновились. */
  const liveStripText = () => {
    const live = liveStrip()
    return live === null ? null : String(live.textContent ?? '').replace(/\s+/gu, ' ').trim()
  }

  /**
   * Запомнить разметку живой полосы.
   *
   * Клонируется весь док, а не только блок статистики: третья ячейка полосы —
   * индикатор занятой памяти — живёт рядом с ним, отдельным элементом.
   */
  const rememberTemplate = () => {
    if (liveStrip() === null) return
    const dock = document.querySelector(DOCK_SELECTOR)
    if (dock !== null) template = dock.outerHTML
  }

  /**
   * Собрать свою полосу.
   *
   * Клон живой полосы сохраняет родные классы, иконки и вёрстку. Если живой
   * полосы нет (новый чат), числа в подписях заменяются нулями; если она есть,
   * но не видна, значения оставляем настоящими — человеку нужны цифры, а не
   * нули. Совсем без живой полосы показываем запасной текст.
   *
   * @param keepValues - сохранять числа живой полосы, а не обнулять их.
   */
  const buildEmpty = (keepValues) => {
    if (template === '') {
      const fallback = document.createElement('div')
      fallback.className = `${EMPTY_STATS_CLASS} ${EMPTY_STATS_BAR_CLASS}`
      fallback.setAttribute('aria-hidden', 'true')
      fallback.innerHTML = EMPTY_STATS_HTML
      return fallback
    }
    const holder = document.createElement('div')
    holder.innerHTML = template
    const bar = holder.firstElementChild
    if (bar === null) return buildEmpty(keepValues)
    bar.classList.add(EMPTY_STATS_BAR_CLASS)
    bar.setAttribute('aria-hidden', 'true')
    // Клон не должен выглядеть живой полосой для собственного поиска.
    for (const marked of bar.querySelectorAll(STATS_ROOT_SELECTOR)) {
      marked.removeAttribute('data-composer-stats')
    }
    bar.removeAttribute('data-composer-stats')
    if (!keepValues) {
      // Числа — в нули: в новом чате шагов и токенов ещё нет.
      const walker = document.createTreeWalker(bar, NodeFilter.SHOW_TEXT)
      for (let node = walker.nextNode(); node !== null; node = walker.nextNode()) {
        if (node.textContent !== null && /\d/u.test(node.textContent)) {
          node.textContent = node.textContent.replace(STATS_NUMBER_PATTERN, '0')
        }
      }
      // Кольцо памяти скопировалось бы заполненным на прошлый процент: раз в
      // подписи ноль, заливку убираем — остаётся пустая дорожка.
      for (const fill of bar.querySelectorAll("[class$='_fill']")) fill.remove()
    }
    // Клон — картинка, а не орган управления: обработчиков у него нет.
    for (const el of bar.querySelectorAll('*')) {
      for (const name of ['aria-label', 'aria-haspopup', 'aria-expanded', 'tabindex', 'role']) {
        el.removeAttribute(name)
      }
    }
    for (const button of bar.querySelectorAll('button')) {
      button.disabled = true
      button.setAttribute('tabindex', '-1')
    }
    return bar
  }

  /**
   * Показать или убрать свою полосу.
   * @param show - нужна ли своя полоса.
   * @param text - текст живой полосы (null, если её нет): по нему клон
   *   пересобирается, когда значения меняются.
   */
  const syncEmpty = (show, text) => {
    if (!show) {
      if (empty !== null) empty.style.display = 'none'
      return
    }
    if (empty === null || builtFrom !== template || builtText !== text) {
      const next = buildEmpty(text !== null)
      if (empty !== null) empty.replaceWith(next)
      else document.body.appendChild(next)
      empty = next
      builtFrom = template
      builtText = text
      applyBarStyles(empty)
    }
    empty.style.display = ''
    applyBarStyles(empty)
  }

  /**
   * Поднять док полосы наверх, если CSS до него не достал.
   *
   * Правило в стилях ищет док по суффиксу класса. Если у дока в текущем
   * состоянии оказался ещё один класс (или он вложен иначе), правило не
   * срабатывает, и полоса остаётся внизу — то есть её не видно. Здесь тот же
   * подъём делается напрямую: сначала проверяем, что полоса правда не наверху.
   */
  const liftDock = () => {
    const live = liveStrip()
    if (live === null) return null
    if (live.getBoundingClientRect().top <= 4) return null
    let dock = live.parentElement
    while (dock !== null && !String(dock.className ?? '').includes('_dock')) dock = dock.parentElement
    if (dock === null) return null
    dock.style.position = 'fixed'
    dock.style.top = '0'
    dock.style.left = '0'
    dock.style.right = '0'
    dock.style.zIndex = '50'
    dock.style.padding = '0 16px'
    dock.style.background = 'var(--dsw-alias-bg-base, #fff)'
    return dock
  }

  // Когда живой полосы не видно, помним с какого момента: короткая пауза при
  // загрузке чата не должна подменять полосу нулями.
  let missingSince = 0

  /** Высота полосы: из переменной замера, иначе штатные 26px. */
  const barHeight = () => {
    const measured = Number.parseFloat(getComputedStyle(root).getPropertyValue(DOCK_HEIGHT_VAR))
    return Number.isFinite(measured) && measured >= 20 ? Math.round(measured) : 26
  }

  /**
   * Жёстко задать геометрию своей полосы инлайновыми стилями.
   *
   * Стили слоя — обычные правила в `<style>`: если на устройстве какое-то из них
   * не применилось (непонятный синтаксис, чужая тема перебила каскад), полоса
   * молча исчезала. Инлайновые стили перебивают таблицы стилей, поэтому здесь
   * дублируется всё, без чего полосу не видно.
   *
   * @param bar - элемент своей полосы.
   */
  const applyBarStyles = (bar) => {
    const style = bar.style
    style.position = 'fixed'
    // Полоса стоит вплотную к верху экрана — ровно там, где стояла всегда.
    style.top = '0'
    // По 22px от краёв экрана: левый край полосы совпадает с левым краем кита
    // (20px) и вкладки «Chat» (25px), правый отступает на столько же.
    style.left = `${STATS_BAR_INSET_PX}px`
    style.right = `${STATS_BAR_INSET_PX}px`
    style.height = `${barHeight()}px`
    // Внутренние поля маленькие: цифры встают на ту же вертикаль, что и «Chat».
    style.boxSizing = 'border-box'
    style.padding = '0 3px'
    // Ниже затемнения (55) и панели (60): открытое меню перекрывает полосу, а не
    // наоборот. Полоса при этом остаётся поверх контента чата.
    style.zIndex = '50'
    style.display = 'flex'
    style.alignItems = 'center'
    style.overflow = 'hidden'
    style.borderRadius = '6px'
    style.background = 'var(--dsw-alias-bg-base, #fff)'
    // Полоса только показывает цифры: тапы проходят сквозь неё к живой полосе
    // harness, поэтому плашки-подсказки по-прежнему открываются.
    style.pointerEvents = 'none'
  }

  /**
   * Освободить место полосе в кадре — тоже инлайново.
   *
   * По этому отступу шапка уезжает вниз. Если положиться только на правило в
   * стилях, при его сбое шапка остаётся на месте и накрывает полосу.
   *
   * @param height - сколько места нужно; 0 — убрать отступ.
   */
  const setFramePadding = (height) => {
    const frame = document.querySelector("[class$='_frame']")
    if (frame === null) return
    // Ноль ставим явно: `removeProperty` возвращает правило CSS, а оно резервирует
    // место под полосу всегда — в экономном режиме сверху оставалась пустая полоса.
    frame.style.paddingTop = height > 0 ? `${height}px` : '0px'
  }

  /**
   * Спрятать живую полосу harness целиком.
   *
   * В экономном режиме статистики не должно быть вовсе: ни наверху, ни над полем
   * ввода. Док живёт в разметке harness, поэтому прячем его инлайново — правила
   * слоя могут не достать до него в текущем состоянии.
   *
   * @param hidden - прятать ли полосу.
   */
  const setDockHidden = (hidden) => {
    const dock = document.querySelector(DOCK_SELECTOR)
    if (dock === null) return
    if (hidden) {
      if (dock.style.display !== 'none') dock.style.display = 'none'
      return
    }
    if (dock.style.display === 'none') dock.style.removeProperty('display')
  }

  const measure = () => {
    if (!isNarrow()) {
      syncEmpty(false, null)
      setDockHidden(false)
      missingSince = 0
      setFramePadding(0)
      root.style.removeProperty(DOCK_HEIGHT_VAR)
      return
    }
    // Экономный режим: полосы нет совсем, значит и места под неё не нужно.
    if (isEconomyMode()) {
      syncEmpty(false, null)
      setDockHidden(true)
      missingSince = 0
      root.style.removeProperty(DOCK_HEIGHT_VAR)
      setFramePadding(0)
      return
    }
    setDockHidden(false)
    rememberTemplate()
    liftDock()
    // Своя полоса показывается ВСЕГДА, а живая под ней просто живёт. Почему так:
    // живая полоса может быть на месте в разметке и при этом не видна человеку —
    // её накрывает шапка, её обрезает предок, она оказывается за краем. Проверки
    // видимости ловят не все такие случаи, а цена ошибки — пустая строка сверху.
    // Своя полоса лежит поверх (z-index 200) и не зависит ни от каскада, ни от
    // соседей; значения берутся из живой и обновляются вместе с ней.
    const text = liveStripText()
    syncEmpty(true, text)
    missingSince = 0
    setFramePadding(barHeight())

    const dock = document.querySelector(DOCK_SELECTOR)
    if (dock === null) {
      root.style.removeProperty(DOCK_HEIGHT_VAR)
      return
    }
    const height = Math.round(dock.getBoundingClientRect().height)
    // Ноль означает, что док ещё не разложен. Записать его в переменную значит
    // спрятать и полосу, и место под неё: держим прошлое значение.
    if (height >= 20) root.style.setProperty(DOCK_HEIGHT_VAR, `${height}px`)
    setFramePadding(barHeight())
  }

  measure()
  // Полоса появляется и исчезает вместе с данными сессии, а её высота — вместе
  // с шириной экрана. Опрос раз в секунду дешевле наблюдателя за всем деревом.
  const timer = window.setInterval(measure, 1000)
  window.addEventListener('resize', measure)
  window.addEventListener('orientationchange', measure)
  // Переключение режима меняет и наличие статистики, и отступ кадра.
  window.addEventListener(MODE_CHANGE_EVENT, measure)

  return () => {
    clearInterval(timer)
    window.removeEventListener('resize', measure)
    window.removeEventListener('orientationchange', measure)
    window.removeEventListener(MODE_CHANGE_EVENT, measure)
    setDockHidden(false)
    if (empty !== null) empty.remove()
    empty = null
    root.style.removeProperty(DOCK_HEIGHT_VAR)
  }
}
// 13-layout.js — установка и снятие частей слоя по ширине экрана.
function trackLayout() {
  const narrow = window.matchMedia(`(max-width: ${NARROW_MAX_PX}px)`)
  let teardown = []

  const release = () => {
    for (const dispose of teardown.reverse()) dispose()
    teardown = []
  }

  const install = () => {
    if (!isNarrow()) {
      // Широкий экран: снимаем всё, что навязывало телефонное поведение.
      release()
      return
    }
    if (teardown.length > 0) return
    teardown = [
      installPanelState(),
      installHeaderStatus(),
      installStatsDock(),
      installDrawer(),
      installNewChatButton(),
      installSettingsScroll(),
      installSessionLoading(),
      installScrollButton(),
    ]
  }

  install()
  // `addEventListener` у MediaQueryList есть в том же Chrome и Safari, что и
  // сам слой; проверка на месте нужна, чтобы старый браузер не уронил установку
  // всего слоя.
  if (typeof narrow.addEventListener === 'function') narrow.addEventListener('change', install)

  return () => {
    if (typeof narrow.removeEventListener === 'function') narrow.removeEventListener('change', install)
    release()
  }
}
// 14-apply.js — точка входа клиентской половины.
// `slots` — реестр слотов интерфейса.
const inject = ['slots']

/**
 * Включить мобильный слой и раздел настроек.
 * @param ctx - контекст браузерного плагина.
 */
function apply(ctx) {
  try {
    // Раздел «Сервер» убран: всё, что нужно, собрано в одном разделе Mobile UI.
    installSettingsSection(ctx)
    ctx.effect(() => {
      installStyles()
      // Режимы применяются раньше остального: от них зависит, что показывать.
      const uninstallModes = installModes()
      const uninstallLazyMedia = installLazyMedia()
      const uninstallVpnHint = installVpnHint()
      const uninstallMeta = installViewportMeta()
      const uninstallAppIcons = installAppIcons()
      const uninstallViewport = installViewportTracking()
      const uninstallHeaderActions = installHeaderActions()
      const uninstallLayout = trackLayout()
      return () => {
        uninstallLayout()
        uninstallHeaderActions()
        uninstallViewport()
        uninstallAppIcons()
        uninstallMeta()
        uninstallVpnHint()
        uninstallLazyMedia()
        uninstallModes()
        removeStyles()
      }
    }, 'dsh-plugin-mobile-ui: mobile layer')
  } catch (error) {
    // Слой косметический: его сбой не должен ломать загрузку интерфейса.
    console.warn(`dsh-plugin-mobile-ui: could not install the mobile layer: ${String(error)}`)
  }
}

exports.apply = apply;
exports.inject = inject;
